// Agrupar todas las keywords en un array simple
const keywords = $input.all().map(item => item.json.keyword_principal);

return [{
  json: {
    keywords: keywords,
    metadata: {
      total: keywords.length,
      source: 'postgresql'
    }
  }
}];

// Construir el prompt de clustering basado en Prompt #1
const keywords = $json.keywords;

const prompt = `Actúa como un especialista en SEO y estrategia de contenidos.

Recibirás un listado de keywords provenientes de Google Keyword Planner o ingreso manual.

Tu objetivo es:
1. Analizar todas las keywords y eliminar las irrelevantes, duplicadas o con muy poca intención de búsqueda.
2. Detectar las que tienen mayor potencial para crear contenido que atraiga tráfico orgánico.
3. Agruparlas por temáticas basadas en similitud semántica.
4. Dentro de cada grupo, seleccionar:
   - Keyword principal: la más representativa y con mejor potencial.
   - Keywords secundarias: complementos y variaciones (2-5 por cluster).
5. Mantener el idioma original de las keywords.

**Entrada:**
${JSON.stringify({keywords: keywords}, null, 2)}

**Formato de salida (JSON válido, sin markdown):**
{
  "Tema_1": {
    "Keyword_Principal": "palabra clave principal",
    "Keywords_Secundarias": ["keyword1", "keyword2", "keyword3"]
  },
  "Tema_2": {
    "Keyword_Principal": "palabra clave principal",
    "Keywords_Secundarias": ["keyword4", "keyword5"]
  }
}

IMPORTANTE: Responde SOLO con el JSON, sin bloques de código markdown.`;

return [{
  json: {
    prompt: prompt,
    original_keywords: keywords
  }
}];

// Parse respuesta de OpenAI y convertir a array de clusters
let response = $json.message?.content || $json.text || $json.response;

// Limpiar respuesta (remover markdown code blocks si existen)
response = response.trim();
if (response.startsWith('```json')) {
  response = response.replace(/```json\n?/g, '').replace(/```\n?$/g, '');
} else if (response.startsWith('```')) {
  response = response.replace(/```\n?/g, '');
}

// Parse JSON
let clusters;
try {
  clusters = JSON.parse(response);
} catch (error) {
  throw new Error('Error al parsear respuesta de OpenAI: ' + error.message + '\nRespuesta: ' + response);
}

// Convertir a array de clusters
const clustersArray = [];
for (const [temaKey, temaData] of Object.entries(clusters)) {
  clustersArray.push({
    cluster_name: temaKey.replace('Tema_', 'Cluster '),
    keyword_principal: temaData.Keyword_Principal,
    keywords_secundarias: temaData.Keywords_Secundarias
  });
}

return clustersArray.map(cluster => ({
  json: cluster
}));

// Preparar datos para insertar en PostgreSQL
const cluster = $json;
const clusterName = cluster.cluster_name;
const keywordPrincipal = cluster.keyword_principal;
const keywordsSecundarias = cluster.keywords_secundarias;

return [{
  json: {
    cluster_name: clusterName,
    keyword_principal: keywordPrincipal,
    keywords_secundarias: JSON.stringify(keywordsSecundarias),
    all_keywords: [keywordPrincipal, ...keywordsSecundarias]
  }
}];

const insertedItems = $items('Insertar Cluster', 0) || [];
const preparedItems = $items('Preparar Datos Cluster', 0) || [];
const originalKeywords = $items('Preparar Array Keywords', 0)?.[0]?.json?.keywords || [];

function parseSecundarias(value) {
  if (Array.isArray(value)) return value;
  if (value == null) return [];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      return JSON.parse(trimmed);
    } catch {
      return trimmed.split(',').map(v => v.trim()).filter(Boolean);
    }
  }
  return [];
}

const combined = insertedItems.map((item, index) => {
  const base = item?.json || {};
  const prepared = preparedItems[index]?.json || {};
  const secundarias = parseSecundarias(prepared.keywords_secundarias);
  return {
    id: base.id || null,
    cluster_name: base.cluster_name || prepared.cluster_name || '',
    keyword_principal: base.keyword_principal || prepared.keyword_principal || '',
    keywords_secundarias: secundarias,
    total_keywords_secundarias: secundarias.length
  };
});

const allKeywordsFlat = Array.isArray(originalKeywords)
  ? originalKeywords.filter(Boolean)
  : [];
const newClusterIds = combined
  .map(entry => entry.id)
  .filter(Boolean);

return [{
  json: {
    all_clusters: combined,
    all_keywords: allKeywordsFlat,
    new_cluster_ids: newClusterIds
  }
}];

// Lee entradas
const clusters = $json.all_clusters || [];
const allKeywords = $json.all_keywords || [];

// Helpers
function safeParseArray(s) {
  try {
    const v = JSON.parse(s);
    return Array.isArray(v) ? v : [];
  } catch {
    return [];
  }
}
function normalizeSecundarias(v) {
  if (Array.isArray(v)) return v;
  if (v == null) return [];
  if (typeof v === 'string') {
    const t = v.trim();
    if (!t) return [];
    // si ya es JSON ([...]) parsea; si no, intenta split por comas
    return t.startsWith('[') ? safeParseArray(t) : t.split(',').map(x => x.trim()).filter(Boolean);
  }
  return [];
}

// Construye detalle de clusters
const details = clusters.map(c => {
  const secundarias = normalizeSecundarias(c.keywords_secundarias);
  return {
    cluster_name: c.cluster_name ?? '',
    keyword_principal: c.keyword_principal ?? '',
    keywords_secundarias: secundarias,
    total_keywords_secundarias: secundarias.length,
    id: c.id ?? null,
  };
});

// Respuesta final
return [{
  json: {
    success: true,
    total_keywords_processed: Array.isArray(allKeywords) ? allKeywords.length : 0,
    total_clusters_created: details.length,
    clusters_details: details,
    processing_time: new Date().toISOString(),
  }
}];

// No hay keywords pendientes
return [{
  json: {
    status: 'info',
    message: 'No hay keywords pendientes para procesar',
    total_keywords_processed: 0,
    total_clusters_created: 0,
    clusters_details: []
  }
}];
